:root {
  --bg: oklch(96.2% 0.017 76);
  --bg-soft: oklch(93.5% 0.025 76);
  --text: oklch(20.5% 0.006 76);
  --muted: oklch(42% 0.018 76);
  --line: oklch(82% 0.023 76);
  --terracotta: oklch(66% 0.095 43);
  --sage: oklch(73% 0.055 135);
  --sand: oklch(82% 0.057 82);
  --clay: oklch(58% 0.066 35);
  --cream-deep: oklch(90% 0.032 78);
  --max: 1560px;
  --gutter: clamp(1.25rem, 4vw, 4rem);
  --serif: 'Playfair Display', Georgia, serif;
  --sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

* { box-sizing: border-box; }

html {
  background: var(--bg);
  color: var(--text);
  font-family: var(--sans);
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-height: 100vh;
  background:
    radial-gradient(circle at 12% 8%, oklch(91% 0.042 48 / .42), transparent 28rem),
    radial-gradient(circle at 92% 28%, oklch(84% 0.038 135 / .28), transparent 24rem),
    var(--bg);
  color: var(--text);
  font-size: clamp(16px, 1vw, 18px);
  line-height: 1.55;
  text-rendering: optimizeLegibility;
}

body.menu-open { overflow: hidden; }

::selection {
  background: var(--terracotta);
  color: var(--bg);
}

a {
  color: inherit;
  text-decoration: none;
}

img, svg { display: block; max-width: 100%; }

.site-shell {
  width: min(100%, var(--max));
  margin: 0 auto;
  padding: 0 var(--gutter);
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: oklch(96.2% 0.017 76 / .82);
  border-bottom: 1px solid oklch(82% 0.023 76 / .35);
  backdrop-filter: blur(18px);
}

.navbar {
  min-height: 84px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
}

.logo {
  font-family: var(--serif);
  font-size: clamp(1.25rem, 2vw, 1.65rem);
  font-weight: 800;
  letter-spacing: -.035em;
}

.desktop-nav {
  display: flex;
  align-items: center;
  gap: clamp(1rem, 2.5vw, 2.5rem);
  font-size: .84rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.desktop-nav a,
.mobile-panel a,
.contact-links a {
  position: relative;
}

.desktop-nav a::after,
.contact-links a::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  bottom: -.3em;
  height: 1px;
  background: currentColor;
  transform: scaleX(0);
  transform-origin: right;
  transition: transform .35s ease;
}

.desktop-nav a:hover::after,
.contact-links a:hover::after {
  transform: scaleX(1);
  transform-origin: left;
}

.menu-toggle {
  display: none;
  width: 48px;
  height: 48px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: transparent;
  color: var(--text);
  cursor: pointer;
  place-items: center;
  z-index: 80;
}

.menu-toggle span,
.menu-toggle span::before,
.menu-toggle span::after {
  width: 18px;
  height: 1.5px;
  background: currentColor;
  display: block;
  transition: transform .3s ease, opacity .3s ease;
}

.menu-toggle span { position: relative; }
.menu-toggle span::before,
.menu-toggle span::after { content: ''; position: absolute; left: 0; }
.menu-toggle span::before { top: -6px; }
.menu-toggle span::after { top: 6px; }

.menu-open .menu-toggle span { background: transparent; }
.menu-open .menu-toggle span::before { transform: translateY(6px) rotate(45deg); }
.menu-open .menu-toggle span::after { transform: translateY(-6px) rotate(-45deg); }

.mobile-panel {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: grid;
  place-items: center;
  background: var(--bg);
  opacity: 0;
  pointer-events: none;
  transform: translateY(-1rem);
  transition: opacity .35s ease, transform .35s ease;
}

.menu-open .mobile-panel {
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0);
}

.mobile-panel nav {
  display: grid;
  gap: .35rem;
  text-align: center;
}

.mobile-panel a {
  font-family: var(--serif);
  font-size: clamp(3rem, 14vw, 7rem);
  font-weight: 800;
  letter-spacing: -.07em;
  line-height: .95;
}

.eyebrow {
  margin: 0 0 1.2rem;
  color: var(--muted);
  font-size: .78rem;
  font-weight: 800;
  letter-spacing: .14em;
  text-transform: uppercase;
}

.hero {
  padding: clamp(5rem, 11vw, 11rem) 0 clamp(3.5rem, 8vw, 7rem);
}

.hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(16rem, .38fr);
  gap: clamp(2rem, 6vw, 7rem);
  align-items: end;
}

.hero h1,
.page-title,
.contact-title {
  margin: 0;
  font-family: var(--serif);
  font-weight: 800;
  letter-spacing: -.075em;
  line-height: .9;
}

.hero h1 {
  max-width: 13ch;
  font-size: clamp(4.2rem, 11vw, 13.5rem);
}

.hero-note {
  max-width: 25rem;
  margin: 0 0 .6rem;
  color: var(--muted);
  font-size: clamp(1rem, 1.45vw, 1.35rem);
}

.media-showcase {
  display: grid;
  grid-template-columns: 1.08fr .84fr 1fr;
  gap: clamp(.75rem, 1.6vw, 1.5rem);
  padding-bottom: clamp(5rem, 10vw, 9rem);
}

.media-card {
  min-height: clamp(22rem, 45vw, 42rem);
  padding: clamp(1rem, 2vw, 2rem);
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  overflow: hidden;
  color: oklch(19% 0.012 65 / .76);
}

.media-card:nth-child(1) { background: linear-gradient(140deg, var(--terracotta), oklch(76% 0.063 53)); border-radius: 999px 999px 2rem 2rem; }
.media-card:nth-child(2) { background: linear-gradient(180deg, var(--sage), oklch(86% 0.035 126)); margin-top: clamp(4rem, 9vw, 9rem); border-radius: 2rem; }
.media-card:nth-child(3) { background: linear-gradient(30deg, var(--sand), oklch(88% 0.043 70)); margin-top: clamp(1.25rem, 3vw, 3rem); border-radius: 2rem 2rem 999px 999px; }

.media-index,
.media-label {
  font-size: .78rem;
  font-weight: 800;
  letter-spacing: .13em;
  text-transform: uppercase;
}

.marquee-section {
  padding: clamp(3rem, 7vw, 7rem) 0;
  border-block: 1px solid var(--line);
  overflow: hidden;
}

.marquee-row {
  display: flex;
  overflow: hidden;
  user-select: none;
  mask-image: linear-gradient(to right, transparent, black 8%, black 92%, transparent);
}

.marquee-track {
  flex-shrink: 0;
  min-width: 100%;
  display: flex;
  align-items: center;
  gap: clamp(1.4rem, 3vw, 3rem);
  padding: .25rem clamp(.7rem, 1.4vw, 1.25rem);
  animation: marquee 34s linear infinite;
  will-change: transform;
}

.marquee-row.reverse .marquee-track { animation-name: marqueeReverse; animation-duration: 39s; }
.marquee-row.slow .marquee-track { animation-duration: 44s; }

.marquee-track span {
  font-family: var(--serif);
  font-size: clamp(2.4rem, 7vw, 8rem);
  font-weight: 800;
  letter-spacing: -.06em;
  line-height: 1;
  white-space: nowrap;
}

.marquee-track i {
  width: .26em;
  height: .26em;
  border-radius: 999px;
  background: var(--clay);
  flex: 0 0 auto;
  opacity: .65;
}

@keyframes marquee { from { transform: translateX(0); } to { transform: translateX(-100%); } }
@keyframes marqueeReverse { from { transform: translateX(-100%); } to { transform: translateX(0); } }

.about {
  padding: clamp(6rem, 12vw, 12rem) 0;
}

.text-grid {
  display: grid;
  grid-template-columns: minmax(8rem, .35fr) minmax(0, .75fr);
  gap: clamp(2rem, 8vw, 10rem);
}

.about-copy,
.philosophy-copy,
.service-intro {
  max-width: 56rem;
  font-family: var(--serif);
  font-size: clamp(2rem, 4.3vw, 5.4rem);
  font-weight: 700;
  letter-spacing: -.055em;
  line-height: .98;
}

.about-copy p,
.philosophy-copy p { margin: 0 0 1em; }
.about-copy p:last-child,
.philosophy-copy p:last-child { margin-bottom: 0; }

.page-hero {
  padding: clamp(5rem, 10vw, 10rem) 0 clamp(3rem, 8vw, 8rem);
}

.page-title {
  font-size: clamp(4.8rem, 13vw, 15rem);
}

.page-kicker {
  max-width: 39rem;
  margin: clamp(1.5rem, 3vw, 3rem) 0 0 auto;
  color: var(--muted);
  font-size: clamp(1.05rem, 1.4vw, 1.32rem);
}

.letter-wrap {
  padding: clamp(4rem, 8vw, 8rem) 0 clamp(7rem, 13vw, 13rem);
}

.letter-layout {
  display: grid;
  grid-template-columns: minmax(10rem, .38fr) minmax(0, 46rem) minmax(5rem, .2fr);
  gap: clamp(1.5rem, 5vw, 6rem);
}

.letter-meta {
  color: var(--muted);
  font-size: .85rem;
  font-weight: 750;
  letter-spacing: .11em;
  line-height: 1.9;
  text-transform: uppercase;
}

.letter-body p {
  margin: 0 0 1.75em;
  font-family: var(--serif);
  font-size: clamp(1.55rem, 2.45vw, 2.75rem);
  font-weight: 600;
  letter-spacing: -.036em;
  line-height: 1.2;
}

.letter-body p:first-child::first-letter {
  float: left;
  padding: .1em .12em 0 0;
  color: var(--clay);
  font-size: 5.3em;
  line-height: .72;
}

.signature {
  display: inline-block;
  margin-top: 1rem;
  font-family: var(--serif);
  font-size: clamp(2rem, 4vw, 4rem);
  font-weight: 800;
  letter-spacing: -.06em;
}

.philosophy {
  padding: clamp(5rem, 10vw, 10rem) 0 clamp(3rem, 7vw, 7rem);
}

.rule {
  width: min(100% - calc(var(--gutter) * 2), var(--max));
  height: 1px;
  margin: 0 auto;
  background: var(--line);
}

.services-list {
  padding: clamp(4rem, 8vw, 8rem) 0 clamp(7rem, 12vw, 12rem);
}

.service-intro {
  max-width: 13ch;
  margin: 0 0 clamp(4rem, 8vw, 8rem);
}

.service-item {
  display: grid;
  grid-template-columns: minmax(10rem, .34fr) minmax(0, .82fr);
  gap: clamp(1.5rem, 6vw, 8rem);
  padding: clamp(2.25rem, 5vw, 5rem) 0;
  border-top: 1px solid var(--line);
}

.service-item:last-child { border-bottom: 1px solid var(--line); }
.service-item h2,
.client-card h2 {
  margin: 0;
  font-family: var(--serif);
  font-weight: 800;
  letter-spacing: -.052em;
  line-height: 1;
}

.service-item h2 { font-size: clamp(2.6rem, 5.7vw, 7rem); }
.service-item p {
  max-width: 48rem;
  margin: .15rem 0 0;
  font-size: clamp(1.05rem, 1.45vw, 1.35rem);
  line-height: 1.68;
}

.clients-heading {
  padding: clamp(5rem, 9vw, 9rem) 0 clamp(2rem, 5vw, 5rem);
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border-top: 1px solid var(--line);
  border-left: 1px solid var(--line);
  margin-bottom: clamp(6rem, 11vw, 11rem);
}

.client-card {
  min-height: clamp(15rem, 20vw, 22rem);
  padding: clamp(1.5rem, 3vw, 3rem);
  border-right: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  background: oklch(96.5% 0.017 76 / .5);
  transition: background .35s ease;
}

.client-card:hover { background: var(--cream-deep); }
.client-card h2 { font-size: clamp(2rem, 3.6vw, 4.4rem); }
.client-card p {
  max-width: 25rem;
  margin: clamp(1.1rem, 2vw, 2rem) 0 0;
  color: var(--muted);
  line-height: 1.58;
}

.contact-page {
  min-height: calc(100vh - 85px);
  display: grid;
  align-items: center;
  padding: clamp(3rem, 8vw, 8rem) 0;
}

.contact-title {
  text-align: center;
  font-size: clamp(5.8rem, 23vw, 27rem);
}

.contact-links {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: clamp(1.5rem, 4vw, 4rem);
  margin-top: clamp(2rem, 3vw, 3rem);
  color: var(--muted);
  font-family: var(--serif);
  font-size: clamp(1.55rem, 3vw, 3.4rem);
  font-weight: 800;
  letter-spacing: -.045em;
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .001ms !important; animation-iteration-count: 1 !important; scroll-behavior: auto !important; transition-duration: .001ms !important; }
}

@media (max-width: 860px) {
  .desktop-nav { display: none; }
  .menu-toggle { display: grid; }
  .navbar { min-height: 72px; }
  .hero-grid,
  .text-grid,
  .letter-layout,
  .service-item { grid-template-columns: 1fr; }
  .hero h1 { max-width: 9.3ch; }
  .media-showcase { grid-template-columns: 1fr; }
  .media-card { min-height: 24rem; border-radius: 1.5rem !important; margin-top: 0 !important; }
  .marquee-track span { font-size: clamp(3rem, 15vw, 6rem); }
  .about-copy,
  .philosophy-copy,
  .service-intro { font-size: clamp(2.5rem, 12vw, 5rem); }
  .letter-meta { order: -1; }
  .clients-grid { grid-template-columns: 1fr; }
  .client-card { min-height: 13rem; }
}

@media (min-width: 861px) and (max-width: 1120px) {
  .clients-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
EOF

cat > /app/output/script.js <<'EOF'
(function () {
  const toggle = document.querySelector('[data-menu-toggle]');
  const panel = document.querySelector('[data-mobile-panel]');
  const links = document.querySelectorAll('[data-mobile-panel] a');

  if (!toggle || !panel) return;

  function setOpen(isOpen) {
    document.body.classList.toggle('menu-open', isOpen);
    toggle.setAttribute('aria-expanded', String(isOpen));
    panel.setAttribute('aria-hidden', String(!isOpen));
  }

  toggle.addEventListener('click', () => {
    setOpen(!document.body.classList.contains('menu-open'));
  });

  links.forEach((link) => {
    link.addEventListener('click', () => setOpen(false));
  });

  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') setOpen(false);
  });
}());
